if(t==='next'&&p==='medicalroll'&&s.context.treatmentAmounts){assert(s.currentRoll,'Сначала определи компенсацию.');const total=s.currentRoll.total,rate=medicalRate(s,total);const values=s.context.treatmentAmounts;const cost=values.reduce((a,n)=>a+n*5000,0);s.context.losses.forEach((l,i)=>s.stats[l.index]+=values[i]);s.medicalDue+=cost*(1-rate);const injury=s.injuries.at(-1);if(injury){injury.restoredAmounts=values.slice();injury.restored=values.every((n,i)=>n===s.context.losses[i].amount)}journal(s,`Частичное/полное лечение: ${cost} Кр, компенсация ${rate*100}%, счёт ${cost*(1-rate)} Кр.`,'с. 37');delete s.context.treatmentAmounts;route(s,s.context.injuryAfter);return true}
